import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_keeps_last_input_for_each_id_then_sorts():
    events = parse_transcript_log(["b,9,1", "c,1,0", "b,2,0", "a,2,1"])
    assert dedupe_transcripts(events) == [events[1], events[3], events[2]]


def test_parse_transcript_log_trims_fields_and_skips_lines():
    assert parse_transcript_log(["", "  ", "  # ignored", " a , 2 , 0 ", "b,3, "]) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["missing,1", "extra,1,0,1", "x,not-an-integer,1"])
def test_parse_error_uses_original_line_position(bad):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# comment", "a,3,1", "", bad])


def test_daily_counts_and_trailing_window():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,4,0", "e,6,1"])
    counts = daily_flag_counts(events, 2, 5)
    assert counts == [2, 0, 0, 0]
    assert daily_flag_counts(events, 5, 2) == []
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 3) == 0
    assert flags_in_window(counts, 5) == 2


def test_summary_weights_transcripts_and_includes_days_without_events():
    groups = {
        "a": parse_transcript_log(["a,1,1", "b,1,1"]),
        "b": parse_transcript_log(["c,4,0"]),
        "c": [],
    }
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rates_and_ranking():
    groups = {"z": [{"flagged": True}], "none": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("none", None), ("z", 1.0)]
    assert top_flagged_groups(groups, 4) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]


def test_longest_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([2, 1, -1, 2, 0, 1]) == 2
    assert longest_flag_streak([]) == 0

